package storage

import (
	"testing"

	"github.com/NVIDIA/knetscan/knetscan/pkg/portscanner"
	"github.com/stretchr/testify/assert"
)

func TestStore(t *testing.T) {
	testCases := []struct { // Other test cases are covered in storage_test.go
		testName       string
		expectedStatus string
		expectedError  string
	}{
		{
			"Test bad value for storage type",
			"",
			"bad store type BAD_VALUE configured",
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.testName, func(t *testing.T) {
			dir := &directory{stType: "BAD_VALUE"}
			status, err := dir.Store(portscanner.ScanResult{})
			assert.Equal(t, testCase.expectedStatus, status, "Unexpected status returned")
			assert.EqualError(t, err, testCase.expectedError, "Unexpected error returned")
		})
	}
}

