package storage

import (
	"io"
	"net/http"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/NVIDIA/knetscan/knetscan/pkg/portscanner"
	"github.com/Ullaakut/nmap/v3"
	"github.com/elastic/go-elasticsearch/v8"
	"github.com/stretchr/testify/assert"
)

func TestPostToLocalStorage(t *testing.T) {
	var dummyScanInfo nmap.ScanInfo
	testCases := []struct {
		testName         string
		testDirPath      string
		testScanOutput   portscanner.ScanResult
		expectedFilePath string
		expectedFileData string
	}{
		{
			"Success Test: Valid write to json file",
			"./",
			portscanner.ScanResult{
				Timestamp:         time.Date(2020, 12, 31, 1, 2, 3, 123123123, time.UTC),
				ScannerIP:         "192.168.0.1",
				TargetScanResults: nil,
				ScanInfo:          dummyScanInfo,
			},
			"./192.168.0.1-1609376523.json",
			"{\n \"@timestamp\": \"2020-12-31T01:02:03.123123123Z\",\n \"scannerIP\": \"192.168.0.1\",\n \"internalScan\": false,\n \"node\": \"\",\n \"targetScanResults\": null,\n \"scanInfo\": {\n  \"num_services\": 0,\n  \"protocol\": \"\",\n  \"scan_flags\": \"\",\n  \"services\": \"\",\n  \"type\": \"\"\n }\n}", //nolint:lll
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.testName, func(t *testing.T) {
			storeClient, err := NewStorageClient(true, testCase.testDirPath, "", "", "", "", "")
			assert.Nil(t, err, "Failed to create storage client")
			_, storeErr := storeClient.Store(testCase.testScanOutput)
			assert.NoError(t, storeErr, "Unexpected error returned")
			byteValue, _ := os.ReadFile(testCase.expectedFilePath)
			writtenData := string(byteValue)
			if writtenData != testCase.expectedFileData {
				t.Errorf("Test failure: File output mismatch : (Found: %s, Expected: %s)", writtenData, testCase.expectedFileData)
			}
			os.Remove(testCase.expectedFilePath)
		})
	}
}

type MockTransport struct {
	Response    *http.Response
	RoundTripFn func(req *http.Request) (*http.Response, error)
}

func (t *MockTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	return t.RoundTripFn(req)
}

func TestPostToElasticSearch(t *testing.T) {
	var dummyScanInfo nmap.ScanInfo
	testCases := []struct {
		testName                      string
		testEsEndpoint                string
		testEsUsername                string
		testEsPassword                string
		testEsCAFingerprint           string
		testEsIndex                   string
		testScanOutput                portscanner.ScanResult
		mockElasticsearchResponseBody string
		expectedResponseStatus        string
	}{
		{
			"Success Test: Valid output posted to elasticsearch",
			"sample.endpoint.com",
			"test-user",
			"test-pass",
			"ABCD123",
			"knetscan-index",
			portscanner.ScanResult{
				Timestamp:         time.Date(2020, 12, 31, 1, 2, 3, 123123123, time.UTC),
				ScannerIP:         "192.168.0.1",
				TargetScanResults: nil,
				ScanInfo:          dummyScanInfo,
			},
			"{}",
			"200 OK",
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.testName, func(t *testing.T) {
			mocktrans := MockTransport{
				Response: &http.Response{
					StatusCode: http.StatusOK,
					Body:       io.NopCloser(strings.NewReader(testCase.mockElasticsearchResponseBody)),
					Header:     http.Header{"X-Elastic-Product": []string{"Elasticsearch"}},
				},
			}
			mocktrans.RoundTripFn = func(_ *http.Request) (*http.Response, error) { return mocktrans.Response, nil }

			client, _ := elasticsearch.NewClient(elasticsearch.Config{
				Transport: &mocktrans,
			})
			storeClient, err := NewStorageClient(false, "", testCase.testEsEndpoint, testCase.testEsUsername,
				testCase.testEsPassword, testCase.testEsCAFingerprint, testCase.testEsIndex)
			assert.Nil(t, err, "Failed to create storage client")
			assert.NotNil(t, storeClient.(*directory).elasticsearchClient, "Failed to create elasticsearch client")
			// Overwrite with the mocked client for further testing
			storeClient.(*directory).elasticsearchClient = client
			responseStatus, storeErr := storeClient.Store(testCase.testScanOutput)
			assert.Nil(t, storeErr, "No error expected in store operation")
			if responseStatus != testCase.expectedResponseStatus {
				t.Errorf("Test failure: Response status does not match : (Found: %s, Expected: %s)",
					responseStatus, testCase.expectedResponseStatus)
			}
		})
	}
}

