var width = 1500;
var height = 1500;
const nodeRadius = 35
const forceStrength = 0.05
const linkDistance = 250
const knownGroups = ["Scanner", "Target#POD", "Target#SERVICE", "Target#NODE", "Target#CUSTOM_ARG", "Target#CUSTOM_FILE"]

// Specify the color scale.
const color = d3.scaleOrdinal(d3.schemeCategory10);

// The force simulation mutates links and nodes, so create a copy
// so that re-evaluating this cell produces the same result.
const links = data.links.map(d => ({ ...d }));
const nodes = data.nodes.map(d => ({ ...d }));
const topnavbar = document.getElementById("topnavbar");

if (nodes.length > 0) {
    width = window.innerWidth;
    height = window.innerHeight - topnavbar.offsetHeight;
}

drag = simulation => {
    function dragstarted(event) {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        event.subject.fx = event.subject.x;
        event.subject.fy = event.subject.y;
    }

    function dragged(event) {
        event.subject.fx = event.x;
        event.subject.fy = event.y;
    }

    function dragended(event) {
        if (!event.active) simulation.alphaTarget(0);
        event.subject.fx = null;
        event.subject.fy = null;
    }

    return d3.drag()
        .on("start", dragstarted)
        .on("drag", dragged)
        .on("end", dragended);
}

function getNeighbors(node) {
    return links.reduce(function (neighbors, link) {
        if (link.target.id === node.id) {
            neighbors.push(link.source.id)
        } else if (link.source.id === node.id) {
            neighbors.push(link.target.id)
        }
        return neighbors
    },
        [node.id]
    )
}

function isNeighborLink(node, link) {
    return link.target.id === node.id || link.source.id === node.id
}

function isNeighborNode(node, neighbors) {
    if (Array.isArray(neighbors) && neighbors.indexOf(node.id) > -1) {
        return true
    }
    return false
}

function selectNode(selectedNode) {
    var neighbors = getNeighbors(selectedNode)
    // we modify the styles to highlight selected nodes
    node
        .attr("display", "none")
        .filter(d => isNeighborNode(d, neighbors))
        .attr("display", "block");

    link
        .attr("display", "none")
        .filter(l => isNeighborLink(selectNode, l))
        .attr("display", "block");

    portsText
        .attr("display", "none")
        .filter(p => isNeighborLink(selectNode, p))
        .attr("display", "block");
}

function resetGraph() {
    node
        .attr("display", "none")
        .filter(d => d.group == knownGroups[0])
        .attr("display", "block");

    link.attr("display", "none");

    portsText.attr("display", "none");
}

function mouseEntered(d, clickedNode) {
    if (clickedNode == null) { return }
    if (d.id == clickedNode.id) {
        link
            .attr("display", "none")
            .filter(l => l.source.id === d.id || l.target.id === d.id)
            .attr("display", "block")
            .attr("stroke-width", 2)
            .style("stroke", color(knownGroups[0]));
        portsText
            .attr("display", "none")
            .filter(l => l.source.id === d.id || l.target.id === d.id)
            .attr("display", "block");
    } else {
        link
            .attr("display", "none")
            .filter(l => (l.source.id === d.id || l.target.id === d.id) && (l.source.id === clickedNode.id || l.target.id === clickedNode.id))
            .attr("display", "block")
            .attr("stroke-width", 2)
            .style("stroke", color(knownGroups[0]));
        portsText
            .attr("display", "none")
            .filter(l => (l.source.id === d.id || l.target.id === d.id) && (l.source.id === clickedNode.id || l.target.id === clickedNode.id))
            .attr("display", "block");
    }
}

function mouseLeft() {
    link
        .attr("display", "none");
    portsText
        .attr("display", "none");
}

// Create a simulation with several forces.
const simulation = d3.forceSimulation(nodes)
    .force("link", d3.forceLink(links).id(d => d.id).distance(linkDistance).strength(forceStrength))
    .force("charge", d3.forceManyBody())
    .force("collide", d3.forceCollide(nodeRadius + 50).iterations(10))
    .force("x", d3.forceX())
    .force("y", d3.forceY());

// Create the graph SVG container.
const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height)
    .attr("viewBox", [-width / 2, -height / 2, width, height])
    .attr("style", "max-width: 100%; height: auto; background-color: #E5E4E2");

const glinks = svg.append("g")
const gports = svg.append("g")
const gnodes = svg.append("g")

// Add a line for each link, and a circle for each node.
const link = glinks.attr("stroke", "#999")
    .attr("stroke-opacity", 0.6)
    .selectAll("line")
    .data(links)
    .join("line")
    .attr("stroke-width", 1)
    .style("stroke", "#858383");

// Add ports text
const portsText = gports.selectAll("g")
    .data(links)
    .join("text")
    .text(d => d.ports)

// Add nodes
const node = gnodes.attr("class", "nodes").attr("id", "node-graph")
    .selectAll("g")
    .data(nodes)
    .enter()
    .append("g")

var nodeCircle = node.append("circle")
    .attr("r", nodeRadius)
    .attr("fill", d => color(d.group))

var enteredNode = null
var clickedNode = null
nodeCircle.call(drag(simulation))
    .on("mouseenter", (evt, d) => {
        mouseEntered(d, clickedNode)
        enteredNode = d
    })
    .on("mouseleave", evt => {
        if (enteredNode != null) {
            mouseLeft()
        }
        enteredNode = null
    })
    .on("click", (evt, d) => {
        clickedNode = d
        resetGraph()
        selectNode(d)
    })
    .enter()
    .append("g")

node.append("text")
    .attr("font-family", "Arial")
    .style("font-size", "14px")
    .style("font-weight", "bold")
    .style("text-anchor", "middle")
    .text(d => d.id);

node.append("title")
    .text(d => d.metadata);

// Add a drag behavior.
node.call(d3.drag()
    .on("start", dragstarted)
    .on("drag", dragged)
    .on("end", dragended));

// Set the position attributes of links and nodes each time the simulation ticks.
simulation.on("tick", () => {
    link
        .attr("x1", d => d.source.x)
        .attr("y1", d => d.source.y)
        .attr("x2", d => d.target.x)
        .attr("y2", d => d.target.y);

    portsText.attr('transform', d => `translate(${(d.source.x + d.target.x) / 2},${(d.source.y + d.target.y) / 2})`);

    node.attr('transform', d => `translate(${d.x},${d.y})`);
});

var baseScale = (width * height) / 6000000;
glinks.attr("transform", `scale(${baseScale})`)
gports.attr("transform", `scale(${baseScale})`)
gnodes.attr("transform", `scale(${baseScale})`)

var isFirstZoom = true;
var zoom = d3.zoom()
    .scaleExtent([baseScale, 20])
    .on('zoom', function (event) {
        if (isFirstZoom) {
            event.transform.k = baseScale;
            isFirstZoom = false;
        }
        event.transform.x = validate(event.transform.x, -width / 2, width / 2)
        event.transform.y = validate(event.transform.y, -height / 2, height / 2)
        glinks.attr('transform', event.transform);
        gports.attr('transform', event.transform);
        gnodes.attr('transform', event.transform);
    });
svg.call(zoom);

function validate(i, min, max) {
    if (i < min) return min
    if (i > max) return max
    return i
}

// Reheat the simulation when drag starts, and fix the subject position.
function dragstarted(event) {
    if (!event.active) simulation.alphaTarget(0.3).restart();
    event.subject.fx = event.subject.x;
    event.subject.fy = event.subject.y;
}

// Update the subject (dragged node) position during drag.
function dragged(event) {
    event.subject.fx = event.x;
    event.subject.fy = event.y;
}

// Restore the target alpha so the simulation cools after dragging ends.
// Unfix the subject position now that it’s no longer being dragged.
function dragended(event) {
    if (!event.active) simulation.alphaTarget(0);
    event.subject.fx = null;
    event.subject.fy = null;
}

// Add legend to bottom right of the screen
const legend = document.getElementById("legend");
for (let i = 0; i < knownGroups.length; i++) {
    const li = document.createElement("li");
    const span = document.createElement("span");
    const circle = document.createElement("span");

    span.innerHTML = knownGroups[i].split("#", 2).pop().toLowerCase();
    span.style.color = '#fff'; // White text color
    span.style.textTransform = 'capitalize'; // Convert text to camelCase

    circle.className = 'circle';
    circle.style.backgroundColor = color(knownGroups[i]); // Color circle based on legend color

    li.appendChild(circle);
    li.appendChild(span);
    legend.appendChild(li);
}

// Search bar operation
const f = document.getElementById('form');
const q = document.getElementById('query');

function goToSearchedElement(nodeID) {
    var searchedNodes = node.filter(d => d.id == nodeID)
    if (searchedNodes.size() == 1) {
        searchedNodes.each(function (d, i) {
            clickedNode = d
            resetGraph()
            selectNode(d)

            s = node
                .filter(e => e.id == d.id)
                .selectAll("circle")
                .style("stroke", "yellow")
                .style("stroke-width", "6px");

            setTimeout(() => {
                s.style("stroke", "")
                    .style("stroke-width", "");
            }, 3000)
        })
        return true;
    }
    return false;
}

function submitted(event) {
    event.preventDefault();
    var searchInput = q.value
    if (!goToSearchedElement(searchInput)) {

        console.log("IP not found: " + searchInput)
        ulElement = document.getElementById("searchResultsUL")
        ulElement.innerHTML = ""
        searchResultsNodeIds = []
        node.each(function (d, i) {
            if (d.id.includes(searchInput) || d.metadata.includes(searchInput)) {
                searchResultsNodeIds.push(d.id)

                var li = document.createElement("li");
                li.setAttribute("class", "dropdown-li")
                li.setAttribute("id", d.id)
                li.setAttribute("onclick", "goToSearchedElement(this.id)")
                li.appendChild(document.createTextNode(d.id + "    (" + d.metadata + ")"));
                ulElement.appendChild(li)
            }
        })
        document.getElementById("searchResultsDropdown").classList.toggle("show");
    }
}

document.onclick = function (e) {
    var navbar = document.getElementById('topnavbar');
    if (!navbar.contains(e.target)) {
        document.getElementById("searchResultsDropdown").classList.toggle("show");
    }
};

f.addEventListener('submit', submitted);

// Append the SVG element.
container.append(svg.node());
resetGraph();

