package storage

import (
	"context"
	"encoding/json"
	"strings"

	"github.com/NVIDIA/knetscan/knetscan/pkg/portscanner"

	"github.com/elastic/go-elasticsearch/esapi"
	"github.com/rs/zerolog/log"
)

// PostToElasticSearch posts the scan output to the elasticsearch endpoint.
func (dir *directory) postToElasticSearch(scanOutput portscanner.ScanResult) (string, error) {
	log.Info().Msgf("Posting to elasticsearch")
	targetScanResultsJSON, _ := json.Marshal(scanOutput)
	ctx := context.Background()
	targetScanResultsString := string(targetScanResultsJSON)
	documentID := portscanner.GenerateUIDForScan(scanOutput)
	req := esapi.IndexRequest{
		Index:      dir.elasticsearchIndexName,
		DocumentID: documentID,
		Body:       strings.NewReader(targetScanResultsString),
		Refresh:    "true",
	}
	// Return an API response object from request
	res, clientErr := req.Do(ctx, dir.elasticsearchClient)
	if clientErr != nil {
		return "", clientErr
	}
	defer res.Body.Close()

	if res.IsError() {
		log.Error().Msgf("%s ERROR indexing document ID=%s\n", res.Status(), documentID)
	} else {
		// Deserialize the response into a map.
		var resMap map[string]interface{}
		if decodeErr := json.NewDecoder(res.Body).Decode(&resMap); decodeErr != nil {
			return "", decodeErr
		}
		log.Info().Msgf("IndexRequest() RESPONSE, Status: %s, Result: %+v", res.Status(), resMap["result"])
	}
	log.Info().Msgf("Posted scan data to elasticsearch")
	return res.Status(), nil
}

