package storage

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/NVIDIA/knetscan/knetscan/pkg/portscanner"
	"github.com/rs/zerolog/log"
)

// PostToLocalStorage posts the nmap scan output to the defined path as a json.
func (dir *directory) postToLocalStorage(scanOutput portscanner.ScanResult) (string, error) {
	outputFilePath := filepath.Join(dir.pathToLocalDir, fmt.Sprint(portscanner.GenerateUIDForScan(scanOutput), ".json"))
	scanOutputJSON, _ := json.MarshalIndent(scanOutput, "", " ")

	writeErr := os.WriteFile(outputFilePath, scanOutputJSON, 0777) //nolint:gosec // We recommend process to be run as sudo
	if writeErr != nil {
		return "", writeErr
	}
	log.Info().Msgf("Posted to local directory at %s", outputFilePath)
	return "OK", nil
}
